for city,services in citynotes.items():
 for service,n in services.items():notes[f'{service}-in-{city}.html']=n
out=['# Probay: page-by-page dossiers','Research date: 29 October 2026. All statements describe observed content or advertised services; they do not certify professional delivery or legal accuracy.','The alternate `/index.html` duplicates the root homepage and is omitted from the 45 dossiers. Section lists describe content order. Forms and metadata below come from captured markup; runtime-generated behavior is documented in the main report.']
for i,p in enumerate([p for p in data if 'text' in p and p['url']!='https://probay.in/index.html'],1):
 s=BeautifulSoup((P/'source'/p['file']).read_text(encoding='utf-8'),'html.parser'); main=s.select_one('main')
 out += [f'\n## {i:02d}. {p["title"]}',f'\nSource: [{p["url"]}]({p["url"]})',f'\n**Purpose and content:** {notes.get(p["file"],"See the captured structure and source evidence.")}']
 sections=[h.get_text(' ',strip=True) for h in main.select('h2') if 'Thanks,' not in h.get_text()]
 out += ['\n**Section sequence:** '+ ' → '.join(sections)+'.']
 if p['forms']:
  form=main.select_one('form');fields=[]
  for x in form.select('input,select'):
   if x.get('name')=='website':continue
   if x.name=='select':
    opts=x.select('option');chosen=next((o for o in opts if o.has_attr('selected')),opts[0] if opts else None)
    fields.append(x.get('name','')+' (select; default '+(chosen.get_text(' ',strip=True) if chosen else '')+')')
   elif x.get('type')=='hidden': fields.append(x.get('name','')+' (hidden: '+(x.get('value') or 'empty until chosen')+')')
   else:fields.append(x.get('name','')+' ('+x.get('type','text')+')')
  out+=['\n**Enquiry fields:** '+ '; '.join(fields)+'. Shared honeypot and validation apply.']
 else:out+=['\n**Enquiry form:** None on this page. Other contact links may be present.']
 out+=['\n**Components:** '+', '.join(f'{len(main.select(sel))} {label}' for sel,label in [('.plan','pricing cards'),('table','tables'),('.tl-item','timeline stages'),('.faq-item','FAQ entries'),('img','main-content images'),('.mini-service','related-service links')])+'.']
 meta=s.find('meta',attrs={'name':'description'});can=s.find('link',rel='canonical')
 out+=['\n**Metadata:** HTTP '+str(p['status'])+'; canonical '+(can.get('href','') if can else 'absent')+'; '+str(len(s.select('h1')))+' H1.']
 if meta:out+=['Description: '+meta.get('content','')]
out+=['\n## Homepage alias','`https://probay.in/index.html` returns HTTP 200 and canonicalises to `https://probay.in/`. Its captured main content equals the root homepage. Counts in the main report de-duplicate this alias.']
(P/'PAGE-BY-PAGE.md').write_text('\n\n'.join(out),encoding='utf-8')
print('Dossiers:',len([p for p in data if 'text' in p and p['url']!='https://probay.in/index.html']))
print('Unmapped:',[p['file'] for p in data if 'text' in p and p['url']!='https://probay.in/index.html' and p['file'] not in notes])
